const u=[{id:"optimism-maier-seligman",title:"O01 · Maier et Seligman · 2016 · Cinquante ans de recherches sur l’impuissance apprise",url:"https://doi.org/10.1037/rev0000033",type:"research",finding:"La revue réexamine l’impuissance apprise : dans les situations aversives étudiées chez l’animal, une stimulation prolongée entraîne la passivité. Détecter une possibilité de contrôle active des circuits protecteurs.",limitation:"Il s’agit surtout d’expériences animales, pas d’une synthèse de traitements humains. Elle ne montre pas que rester figé est une réaction humaine universelle et ne valide pas un exercice de liste de possibilités contrôlables."},{id:"optimism-malouff-schutte",title:"O03 · Malouff et Schutte · 2017 · Les interventions peuvent-elles augmenter l’optimisme ?",url:"https://doi.org/10.1080/17439760.2016.1221122",type:"research",finding:"Dans 29 études randomisées avec 3 319 participants, les interventions psychologiques ont augmenté les scores d’optimisme en moyenne (g = 0,41).",limitation:"Méthodes et suivis variaient. Les suivis courts et les analyses limitées aux personnes ayant terminé donnaient des effets plus grands. L’intervalle de confiance n’a pas été vérifié dans le document consulté. Aucun changement permanent ni effet d’ODA n’est établi."},{id:"optimism-sweeney",title:"O02 · Sweeney, Anderson et Bailey · 1986 · Explications et dépression",url:"https://doi.org/10.1037/0022-3514.50.5.974",type:"research",finding:"Dans 104 études avec près de 15 000 participants, la dépression était associée à des explications internes, stables et globales des événements négatifs.",limitation:"Une association n’établit pas une cause et ne rend pas fausse une explication négative. Le résumé consulté ne permettait pas de vérifier les effets regroupés ni leurs intervalles de confiance. Une reformulation rassurante n’est pas toujours exacte."},{id:"optimism-hofmann",title:"O06 · Hofmann et collègues · 2012 · Revue de méta-analyses des TCC",url:"https://doi.org/10.1007/s10608-012-9476-1",type:"research",finding:"La revue a recensé 269 méta-analyses de TCC et examiné 106 d’entre elles, représentatives. Le soutien concernait des traitements complets et variait selon le problème.",limitation:"Ces nombres ne désignent pas des essais isolés de fiches de pensées et ne valident pas la fiche ODA. Le texte de correction d’un erratum distinct était indisponible pour vérification."},{id:"optimism-brunwasser",title:"O05 · Brunwasser, Gillham et Kim · 2009 · Revue du Penn Resiliency Program",url:"https://doi.org/10.1037/a0017671",type:"research",finding:"Dans 17 études contrôlées avec 2 498 jeunes, le programme en plusieurs séances montrait de petits bénéfices sur les symptômes dépressifs face à l’absence d’intervention.",limitation:"Le bénéfice face à des interventions actives et la prévention de diagnostics dépressifs n’étaient pas établis. Ce programme pour jeunes ne valide pas un exercice ABCDE isolé chez l’adulte."},{id:"optimism-ellis-abc",title:"O12 · Albert Ellis Institute · Présentation professionnelle du modèle ABC",url:"https://albertellis.org/wp-content/uploads/2021/09/Emotional-Disturbance-and-Its-Treatment-in-a-Nutshell-ABCs-.pdf",type:"guidance",finding:"La présentation décrit un événement, les croyances, leurs conséquences, la remise en question des croyances rigides et une nouvelle philosophie efficace.",limitation:"C’est une description de méthode, pas un essai d’efficacité. La dernière étape d’Ellis ne doit pas être confondue avec les versions ultérieures dites d’« énergisation ». Le bref exercice ODA est une adaptation."},{id:"optimism-beck-thought-record",title:"O13 · Beck Institute · Fiche de pensées",url:"https://beckinstitute.org/wp-content/uploads/2021/08/Thought-Record-Worksheet.pdf",type:"guidance",finding:"La fiche clinique consigne la situation, la pensée, l’émotion, les éléments disponibles, une réponse équilibrée et de nouvelles évaluations.",limitation:"C’est une méthode clinique, pas un essai d’efficacité isolée. L’adaptation courte d’ODA n’est pas un traitement TCC. Une réponse équilibrée n’a pas nécessairement à réduire la détresse."},{id:"optimism-reivich-mrt",title:"O14 · Reivich, Seligman et McBride · 2011 · Formation à la résilience",url:"https://doi.org/10.1037/a0021897",type:"guidance",finding:"La présentation du programme comprend ABC, des questions sur les pièges de pensée, puis les possibilités pire, meilleure et la plus probable, suivies d’un plan.",limitation:"Elle décrit une formation de formateurs de dix jours. Elle n’établit pas l’efficacité isolée de ces exercices ni celle du parcours ODA."},{id:"optimism-landau-inquiry",title:"O11 · Landau et collègues · 2021 · Essai de questionnement accompagné",url:"https://doi.org/10.1001/jamanetworkopen.2021.39670",type:"research",finding:"Un essai randomisé enregistré auprès de 100 femmes porteuses de variants BRCA comparait douze semaines de questionnement accompagné aux soins habituels. Il signalait des bénéfices sur certains résultats de bien-être.",limitation:"Les groupes hebdomadaires de trois heures et la pratique accompagnée diffèrent d’une courte leçon en autonomie. Les soins habituels n’offraient pas une attention équivalente. L’équivalence aux TCC et l’application à la maltraitance ou au traumatisme ne sont pas établies."},{id:"optimism-katie-instructions",title:"O15 · Byron Katie International · Instructions de The Work",url:"https://thework.com/instruction-the-work-byron-katie/",type:"technique",finding:"Les instructions de pratique présentent quatre questions, suivies de retournements et d’exemples réels.",limitation:"Des instructions ne sont pas des résultats scientifiques. Les retournements restent facultatifs, sans exemples inventés ni culpabilité imposée. L’essai long et accompagné utilise une autre façon de proposer la méthode."},{id:"optimism-nhs-cbt",title:"O16 · NHS · Thérapie comportementale et cognitive",url:"https://www.nhs.uk/tests-and-treatments/cognitive-behavioural-therapy-cbt/",type:"guidance",finding:"Le NHS décrit un traitement TCC structuré et les voies d’accès à une aide professionnelle.",limitation:"Ces recommandations ne reconnaissent pas ODA comme thérapie et ne garantissent aucune réponse. La protection concrète et les soins professionnels passent avant un exercice de réflexion en autonomie."},{id:"optimism-three-good-things",title:"O07 · Seligman et collègues · 2005 · Interventions de psychologie positive",url:"https://doi.org/10.1037/0003-066X.60.5.410",type:"research",finding:"L’essai original en ligne proposait des exercices d’une semaine. Les « trois bonnes choses » étaient trois événements et leurs causes, chaque soir pendant une semaine.",limitation:"Des 577 répondants initiaux, 411 ont terminé le suivi, surtout des volontaires blancs et diplômés. La poursuite de la pratique n’était pas attribuée au hasard. Cela ne prouve ni maintien garanti ni traitement clinique."},{id:"optimism-mongrain",title:"O08 · Mongrain et Anselmo-Matthews · 2012 · Réplication d’exercices positifs",url:"https://doi.org/10.1002/jclp.21839",type:"research",finding:"La réplication a trouvé des gains de bonheur avec les exercices nommés et un placebo positif. Elle n’a pas démontré de bénéfice propre sur la dépression.",limitation:"Le résumé consulté ne permettait pas de vérifier l’effectif ni les effets chiffrés. Le soutien propre aux exercices est moindre, sans prouver que tout exercice positif est inutile."},{id:"optimism-nimh-support",title:"O20 · NIMH · Recommandations sur la dépression",url:"https://www.nimh.nih.gov/health/publications/depression",type:"guidance",finding:"Des symptômes persistants ou un quotidien perturbé justifient une évaluation professionnelle. Une aide de crise est disponible.",limitation:"Ce sont des recommandations, pas un diagnostic par l’application. Tu n’as pas à attendre deux semaines ni la fin du parcours pour demander de l’aide."}],r=[{schemaVersion:2,revision:2,id:"optimism-1",courseId:"optimism",locale:"fr",title:"Un refus ? Essaie ce qui dépend de toi",goal:"Après un revers sans enjeu grave, essaie un geste utile qui dépend de toi.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Un refus te pousse à abandonner ? Essaie avant de choisir la suite.",reason:{id:"optimism-1-reason-available-step",label:"Quelle possibilité as-tu écartée ? Sur quels faits t’appuies-tu ?",kind:"text",maxLength:160,optional:!0,suggestions:["Vérifier une possibilité écartée","Garder une raison valable d’arrêter","Essayer de répondre à une exigence"]},why:{id:"optimism-1-direction",label:"Pourquoi ce geste compte-t-il dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Un revers et ton prochain geste sont différents. Tu ne peux pas imposer l’approbation de ton travail. Tu peux parfois demander quel point manque, travailler une compétence ou chercher du soutien. Essaie une possibilité précise, sans déclarer toute la situation contrôlable.","Des interventions étudiées ont amélioré les scores d’optimisme en moyenne. Elles mesurent des attentes, pas l’annulation d’un refus. Ce parcours suit un revers ordinaire et une action pour rebondir. Prévois le geste, essaie-le, puis note la réponse, même absente. Une entrée d’agenda prépare l’action ; poser la question, c’est agir."],example:{title:"La question de Camille reste sans réponse",text:"La première version de Camille est refusée. Elle songe à abandonner ce travail qui lui tient à cœur. À 12 h 30, dans un échange d’équipe sans risque, elle demande : « Quel point dois-je corriger en premier ? » Personne ne répond cet après-midi. Elle note sa question envoyée. Elle a essayé d’obtenir un retour, sans prouver que son projet sera accepté."}},move:{invitation:"Après un revers ordinaire, essaie une possibilité et note les faits.",instructions:["Garde ce même revers et ta direction dans tout le parcours.","Choisis un geste réel, pas seulement une entrée dans l’agenda."],prompts:[],suggestions:{action:["Envoyer une question précise sur le travail","Corriger un point manquant déjà identifié","Demander une aide concrète pour ce revers"],minimum:["Envoyer une question claire","Corriger une erreur connue","Faire une demande d’aide concrète"],cue:["Au prochain point d’équipe sans risque","Quand je reprends le texte refusé","Quand une aide est disponible"],place:["Dans un échange de messages sûr","À mon poste habituel"],fallback:["Faire préciser une exigence","Travailler sur une exigence connue","Changer de canal s’il est indisponible"],observation:["Si j’ai envoyé la question","La réponse, ou son absence","Ce qui dépendait de moi"],minutes:[2,1,5],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Envoyer une question précise sur le travail",minimum:"Envoyer une question claire",minutes:2,cueHint:"Au prochain point d’équipe sans risque",placeHint:"Dans un échange de messages sûr",obstacleHint:"Je ne vois pas quelle exigence je pourrais satisfaire.",fallbackHint:"Faire préciser une exigence",observationHint:"Si j’ai envoyé la question"},stopRule:"N’utilise pas cet exercice en cas de danger, maltraitance, automutilation ou symptômes graves. Arrête l’analyse en boucle ; demande du soutien.",accessibleAlternative:"Utilise ton moyen de communication habituel, une aide pratique ou une limite qui te protège."},result:{question:"As-tu fait le minimum que tu avais choisi ?",observationPrompt:"Qu’as-tu fait, et que s’est-il passé ensuite ?"},judgment:{primary:{id:"optimism-1-review-window-decision",scenario:"La première version de Camille est refusée sans explication. Il reste dix minutes pour poser une question à la personne qui l’évalue. Reprendre le projet demanderait deux heures ; Camille veut savoir si cela vaut la peine.",question:"Quel geste éclairerait le mieux sa décision maintenant ?",options:[{id:"optimism-1-inspect-brief",text:"Relire les consignes pendant dix minutes, puis corriger le point qui semble avoir causé le refus.",feedback:"Relire les consignes peut révéler un vrai oubli. Mais la raison du refus reste inconnue, et le temps pour poser une question s’écoule. Demande maintenant ; vérifie ensuite le point concerné."},{id:"optimism-1-ask-criterion",text:"Demander quel point manque, puis choisir une correction faisable à partir de la réponse.",feedback:"Cette option utilise une source d’information encore disponible. La réponse peut justifier une correction, de l’aide ou un arrêt. L’action consiste à envoyer la question ; recevoir une réponse n’est pas nécessaire."},{id:"optimism-1-send-partial-rewrite",text:"Envoyer une version partiellement corrigée en dix minutes, pour montrer son initiative avant la fin des échanges.",feedback:"Une correction partielle pourrait aider si elle vise le vrai problème. Sans explication, Camille devine. Profite de ce créneau pour demander ce qui compte avant d’investir du temps dans une révision."}],bestOptionId:"optimism-1-ask-criterion"}},carry:{takeaway:"Après un revers, essaie ce qui dépend de toi et observe ce que ton geste change.",followUp:{questionId:"optimism-1-return",question:"As-tu saisi la possibilité ? As-tu obtenu une information, aucune réponse ou une nouvelle contrainte ?",observationPrompt:"Quelle information, absence de réponse ou nouvelle contrainte a suivi ton geste ?",adjustmentPrompt:"Quel prochain geste correspond à ce que tu as appris ?"}},goDeeper:{sections:[{heading:"L’explication chez l’animal a été revue",paragraphs:["Maier et Seligman réexaminent en 2016 l’impuissance apprise à partir de recherches animales [O01]. Dans les situations aversives étudiées, une stimulation prolongée entraîne la passivité. Détecter une possibilité de contrôle active des circuits protecteurs. Ces résultats concernent des rats ou chiens soumis à des événements pénibles prolongés, pas l’expérience d’un adulte dont le texte est refusé.","Cette revue ne montre pas que rester figé est la réaction par défaut de chacun. Elle ne ramène pas toute impuissance à un seul mécanisme et ne valide pas une liste de tâches contrôlables comme traitement. La leçon part donc d’une distinction pratique : la décision de l’évaluateur et ta question sont deux événements différents. Elle n’attribue pas ta réaction à une explication cérébrale.","Cet essai en une action pour rebondir est une adaptation ODA. Tu peux constater qu’il change peu de choses. Les contraintes peuvent demander de l’aide ou une autre direction. Garde ce résultat. Un essai réel apporte des informations, sans promettre de te rendre l’espoir."]},{heading:"Des attentes modifiées ne garantissent pas le résultat",paragraphs:["Malouff et Schutte ont regroupé 29 études randomisées avec 3 319 participants [O03]. Les interventions psychologiques ont amélioré les scores d’optimisme en moyenne : g = 0,41. Méthodes, formats et suivis variaient. Les effets étaient plus grands avec des suivis courts ou des analyses limitées aux personnes ayant terminé. Cette moyenne décrit les groupes étudiés, pas l’évolution de tes attentes après un essai.","La revue ne montre ni changement permanent de personnalité, ni meilleurs résultats objectifs, ni effet de ce parcours ODA. Une demande de retour permet de vérifier une exigence. Elle ne garantit pas une acceptation future. La réponse peut néanmoins t’aider à décider si la correction mérite ton temps, demande du soutien ou ne correspond plus à ton projet.","La suite peut être du soutien plutôt qu’une tâche. Le NIMH recommande une évaluation professionnelle si les symptômes persistent ou gênent le quotidien [O20]. Demande de l’aide avant de finir les leçons, sans attendre une durée minimale. Une demande réellement faite peut être une action utile en elle-même."]}],sourceIds:["optimism-maier-seligman","optimism-malouff-schutte","optimism-nimh-support"]}},{schemaVersion:2,revision:2,id:"optimism-2",courseId:"optimism",locale:"fr",title:"Un revers te définit ? Reviens aux faits",goal:"Garde la cause réelle du revers. Essaie une correction précise sans te juger sur tout.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Un texte refusé devient « Je suis incapable » ? Garde les faits et essaie la prochaine correction.",reason:{id:"optimism-2-reason",label:"Que peux-tu changer toi-même ? Qu’est-ce qui reste incertain ?",kind:"text",maxLength:160,optional:!0,suggestions:["Assumer ce que je peux corriger","Garder l’incertitude visible","Reprendre une correction utile"]},why:{id:"optimism-2-direction",label:"Pourquoi ce geste compte-t-il dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Reprends ton revers et les faits notés. La dépression est associée aux explications de revers durables, qui touchent plusieurs domaines et mettent en cause quelque chose en soi. Cette association ne prouve pas de causalité. Toute explication douloureuse n’est pas forcément fausse.","Demande-toi : combien de temps la cause peut-elle durer ? Quel domaine touche-t-elle ? Quelle est ma part, et que reste-t-il à savoir ? Un manque de compétence durable peut être réel. Nomme-le sans faire d’un projet un jugement sur tout. Essaie une correction. Garde ta responsabilité et l’incertitude, sans imposer une explication rassurante."],example:{title:"Camille corrige un point précis",text:"Camille apprend que sa première version ne répond pas à la question du client sur le budget. À 7 h, elle remplace « Je suis nulle » par un constat précis : cette partie est incomplète. Elle ajoute une explication utile et l’envoie. On lui demande encore des détails. La correction a bien été faite ; le résultat global reste ouvert."}},move:{invitation:"Reprends ce revers. Nomme une cause exacte, puis fais la correction indiquée.",instructions:["Garde les contraintes durables et ta part de responsabilité si les faits les confirment.","Fais une correction utile ; note ce qui s’est passé."],prompts:[],suggestions:{action:["Corriger un point demandé","Demander ce qui ne respecte pas les consignes","Essayer une fois la compétence à travailler"],minimum:["Compléter une ligne du projet","Envoyer une question de clarification","Faire un vrai essai de la compétence"],cue:["Quand je rouvre ce texte","À la prochaine occasion sûre de retour","Après avoir lu l’exigence concernée"],place:["Dans le projet que je corrige","Par un canal d’échange sans risque"],fallback:["Relire l’exigence ; corriger un manque confirmé","Demander l’information essentielle qui manque","Demander de l’aide pour la compétence"],observation:["Ce que j’ai corrigé","La cause restée incertaine","Si le retour correspond à mon explication"],minutes:[2,1,5],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Corriger un point demandé",minimum:"Compléter une ligne du projet",minutes:2,cueHint:"Quand je rouvre ce texte",placeHint:"Dans le projet que je corrige",obstacleHint:"Je fais d’un échec un jugement sur tout mon travail.",fallbackHint:"Relire l’exigence ; corriger un manque confirmé",observationHint:"Ce que j’ai corrigé"},stopRule:"N’utilise pas cet exercice en cas de danger, maltraitance, automutilation ou symptômes graves. Arrête l’analyse en boucle ; demande du soutien.",accessibleAlternative:"Utilise ton moyen de communication habituel, une aide pratique ou une limite qui te protège."},result:{question:"As-tu fait le minimum que tu avais choisi ?",observationPrompt:"Qu’as-tu fait, et que s’est-il passé ensuite ?"},judgment:{primary:{id:"optimism-2-budget-gap-decision",scenario:"On signale à Camille une hypothèse manquante dans le budget. Le reste respecte les consignes. Elle a dix minutes pour corriger avant la fin de l’évaluation. Elle pense que cet oubli prouve son incapacité à faire ce travail.",question:"Quelle réponse respecte les faits et le délai ?",options:[{id:"optimism-2-rewrite-budget",text:"Réécrire toute la partie budget maintenant, pour présenter une version entièrement nouvelle à l’évaluation.",feedback:"Tout réécrire peut aider quand plusieurs problèmes sont liés. Ici, une seule hypothèse manque et le temps presse. Corrige cet oubli sans remplacer les éléments déjà acceptés."},{id:"optimism-2-clarify-first",text:"Demander de repréciser l’hypothèse manquante, puis attendre la clarification avant de modifier cette partie.",feedback:"Clarifier aide quand le retour est ambigu. Ici, le point manquant est nommé. Attendre risque de faire perdre le créneau. Fais la correction justifiée, puis demande si elle répond à l’exigence."},{id:"optimism-2-specific-correction",text:"Reconnaître le manque dans le budget, corriger ce point sans conclure sur sa carrière.",feedback:"Cette option assume le manque confirmé et utilise le temps restant pour le corriger. Demande si la correction convient. Les nouveaux retours concernent ce projet ; ils ne tranchent pas l’avenir de ta carrière."}],bestOptionId:"optimism-2-specific-correction"}},carry:{takeaway:"Une explication juste peut rester inconfortable et t’indiquer une correction concrète et utile.",followUp:{questionId:"optimism-2-return",question:"Ta correction visait-elle une cause confirmée ? Quelle partie de l’explication reste inconnue ?",observationPrompt:"Quelle cause confirmée as-tu traitée, et qu’est-ce qui reste inconnu ?",adjustmentPrompt:"Quel manque demande maintenant une correction, une précision ou du soutien ?"}},goDeeper:{sections:[{heading:"Des questions pour être plus précis",paragraphs:["Sweeney et ses collègues ont examiné 104 études, avec près de 15 000 participants [O02]. Dans des groupes et des tâches variés, la dépression était associée à des explications internes, stables et globales des événements négatifs. Ces dimensions portent sur la contribution personnelle, la durée des causes et l’étendue de leurs effets. Elles n’imposent pas une cause unique à un revers. Cette association ne permet pas de savoir quel facteur cause l’autre.","La leçon utilise ces dimensions pour examiner une explication, sans exiger une conclusion heureuse. Une contrainte durable peut rester durable. Un point que tu as oublié peut rester à ta charge. Plusieurs causes peuvent se combiner, et certaines rester inconnues. Remplacer toute explication par « C’est passager et extérieur à moi » ferait perdre en exactitude.","Reviens au même essai suivi dans ce parcours. Que peux-tu corriger, vérifier ou faire avec de l’aide ? Un geste précis se teste plus facilement qu’une affirmation générale sur tes capacités. Distingue ce que tu as fait de ton interprétation du résultat."]},{heading:"Une réponse juste laisse place au vrai problème",paragraphs:["La fiche de pensées du Beck Institute invite à examiner les éléments disponibles, les alternatives, une réponse équilibrée et les observations suivantes [O13]. C’est un outil clinique. Elle ne prouve pas que ce bref exercice d’explication améliore l’humeur à lui seul. L’effet thérapeutique propre à cette adaptation ODA n’est pas établi. Utilise-la pour choisir une correction justifiée, sans exiger une explication rassurante.","Une description équilibrée peut contenir des faits désagréables. Le budget est peut-être incomplet, le délai serré ou la compétence encore à travailler. Elle peut aussi nommer ce qui reste inconnu. Le prochain geste peut être une correction, une question neutre ou une demande de soutien, plutôt qu’une nouvelle phrase rassurante.","Le NHS présente les TCC comme un traitement structuré et explique comment accéder à une aide professionnelle [O16]. Ce parcours est éducatif. Si tes analyses répétées en autonomie augmentent la détresse ou gênent le quotidien, arrête l’exercice et cherche une aide adaptée. Ta sécurité et tes besoins pratiques passent avant une étiquette d’optimisme."]}],sourceIds:["optimism-sweeney","optimism-beck-thought-record","optimism-nhs-cbt"]}},{schemaVersion:2,revision:2,id:"optimism-3",courseId:"optimism",locale:"fr",title:"En colère ? Sépare fait et jugement",goal:"Examine le même revers, puis fais une réponse constructive que tu pourras assumer.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Tu veux te justifier ? Garde les faits et choisis une réponse utile.",reason:{id:"optimism-3-reason",label:"Quelle réponse servira ce qui compte pour toi demain aussi ?",kind:"text",maxLength:160,optional:!0,suggestions:["Assumer une erreur précise","Répondre sans juger toute ma carrière","Résoudre le problème concret"]},why:{id:"optimism-3-direction",label:"Pourquoi ce geste compte-t-il dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Une échéance manquée est un fait. « Je suis incapable de faire ce métier » est une croyance plus large. Un cadre reconnu distingue événement, croyance, émotions et comportements qui suivent. Tes pensées influencent parfois ta réponse. Elles n’expliquent pas toutes tes émotions.","Reprends ton revers. Énonce un fait neutre, confronte la croyance aux éléments disponibles, puis choisis une réponse utile. Si l’inquiétude est fondée, garde-la et traite ce point. Une réponse juste peut assumer ta responsabilité, demander quelque chose ou poser une limite. Tu peux agir même si la gêne ou la colère reste."],example:{title:"Camille assume le retard",text:"Camille manque la nouvelle échéance du rapport. À 6 h 30, elle commence à se justifier, puis distingue le retard de « Je suis incapable de faire ce métier ». Elle écrit : « J’ai manqué le délai. Je peux livrer la partie corrigée demain à midi. Est-ce possible ? » Son responsable accepte, mais reste agacé. Camille note l’accord et le travail restant."}},move:{invitation:"Reprends le même revers. Examine brièvement la croyance, puis fais une réponse juste.",instructions:["Sépare un fait observable du jugement général.","Envoie une correction utile, une demande ou une limite."],prompts:[],suggestions:{action:["Envoyer une réponse qui assume et corrige","Demander un délai réaliste","Terminer une correction convenue"],minimum:["Envoyer une phrase constructive","Indiquer une prochaine étape faisable","Finir une partie utile convenue"],cue:["Avant d’envoyer la réponse difficile","À la prochaine discussion sûre sur la correction","Quand je reprends la tâche convenue"],place:["Dans l’échange professionnel où je peux parler librement","À mon poste de travail habituel"],fallback:["Écrire un fait et une étape faisable ; envoyer","Faire vérifier les faits du message par quelqu’un","Choisir plutôt une aide pratique"],observation:["Ce que j’ai envoyé ou modifié","L’accord obtenu, ou son absence","La partie de l’inquiétude restée vraie"],minutes:[2,1,5],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Envoyer une réponse qui assume et corrige",minimum:"Envoyer une phrase constructive",minutes:2,cueHint:"Avant d’envoyer la réponse difficile",placeHint:"Dans l’échange professionnel où je peux parler librement",obstacleHint:"Je veux me défendre avant de traiter l’erreur réelle.",fallbackHint:"Écrire un fait et une étape faisable ; envoyer",observationHint:"Ce que j’ai envoyé ou modifié"},stopRule:"N’utilise pas cet exercice en cas de danger, maltraitance, automutilation ou symptômes graves. Arrête l’analyse en boucle ; demande du soutien.",accessibleAlternative:"Utilise ton moyen de communication habituel, une aide pratique ou une limite qui te protège."},result:{question:"As-tu fait le minimum que tu avais choisi ?",observationPrompt:"Qu’as-tu fait, et que s’est-il passé ensuite ?"},judgment:{primary:{id:"optimism-3-decision",scenario:"Le responsable de Camille lui reproche, à juste titre, un délai manqué. Elle pense : « Je suis incapable de faire ce métier » et veut se défendre.",question:"Quelle réponse examine sa croyance avec justesse ?",options:[{id:"optimism-3-own-and-correct",text:"Nommer le délai manqué, ne pas conclure sur sa carrière et convenir d’une correction réaliste.",feedback:"Cette réponse garde le fait confirmé et examine la conclusion plus large. Une correction réaliste suit, même si la gêne reste. L’approbation du responsable est un résultat à observer, pas une condition pour avoir agi."},{id:"optimism-3-past-reviews",text:"Relire ses anciens retours favorables jusqu’à ce que la critique semble moins menaçante, puis décider de répondre.",feedback:"Les anciens retours peuvent nuancer un jugement global. Ils ne règlent pas le retard d’aujourd’hui. Attendre le soulagement reporte la réponse pratique. Consulte brièvement les éléments pertinents, puis propose une correction faisable."},{id:"optimism-3-pressure-first",text:"Expliquer la pression subie et demander de reconnaître ses efforts avant de discuter d’une correction.",feedback:"La pression peut être réelle et demander une limite ou du soutien. Exiger d’abord une reconnaissance retarde la correction. Assume le délai manqué tout en demandant un ajustement réaliste."}],bestOptionId:"optimism-3-own-and-correct"}},carry:{takeaway:"Garde le fait réel. Examine le jugement général. Agis à partir d’une conclusion utile.",followUp:{questionId:"optimism-3-return",question:"Ta réponse a-t-elle traité le vrai problème, même si l’émotion difficile est restée ?",observationPrompt:"Quel vrai problème ta réponse a-t-elle traité ?",adjustmentPrompt:"Que reste-t-il à corriger, demander ou limiter ?"}},goDeeper:{sections:[{heading:"D’où vient le cadre en cinq lettres ?",paragraphs:["L’explication professionnelle de l’Albert Ellis Institute décrit l’événement, les croyances et leurs conséquences. Elle propose ensuite de contester les croyances rigides et de construire une nouvelle philosophie efficace [O12]. Des versions ultérieures de formation à la résilience parlent d’« énergisation » pour la dernière étape [O14]. Ces termes ne désignent pas, de façon interchangeable, un changement émotionnel garanti.","Ces sources décrivent des méthodes. Elles n’établissent pas l’efficacité propre à un bref exercice ABCDE chez l’adulte. ODA utilise une version plus courte : décrire le fait, examiner la croyance, puis répondre de façon proportionnée. Les émotions dépendent aussi des circonstances, des pertes, de la santé et du soutien. Un schéma des croyances ne suffit pas à toutes les expliquer.","Dans ton essai, utilise ce cadre seulement s’il répond à une difficulté observée. Tu n’as pas besoin de cinq lettres à chaque action. Si l’inquiétude est fondée, résoudre le problème ou chercher du soutien peut être plus utile que tenter de la faire disparaître en argumentant."]},{heading:"Un programme pour jeunes ne valide pas cet exercice",paragraphs:["Brunwasser et ses collègues ont examiné 17 études contrôlées du Penn Resiliency Program, réunissant 2 498 jeunes [O05]. Par rapport à l’absence d’intervention, les effets sur les symptômes dépressifs étaient petits : d = 0,11 immédiatement, 0,21 à six à huit mois et 0,20 à douze mois. Le bénéfice face à des interventions actives et la prévention des diagnostics dépressifs n’étaient pas établis.","Le programme enseignait plusieurs compétences cognitives et comportementales. Ces résultats ne valident pas un unique exercice ABCDE chez l’adulte et ne prédisent pas l’effet de cet exercice ODA. Apprendre le cadre, enregistrer un plan et envoyer une réponse constructive sont trois événements distincts. Seule la réponse rapportée indique que cette action réelle a eu lieu.","Limite cet essai à un revers ordinaire, sans risque. Un délai manqué peut demander une correction sans devenir un jugement sur ta valeur. Quand un plan dépasse ton temps ou tes moyens, ajuste la demande ou cherche de l’aide. Répéter les mêmes arguments contre toi-même ne remplace pas cet ajustement."]}],sourceIds:["optimism-ellis-abc","optimism-reivich-mrt","optimism-brunwasser"]}},{schemaVersion:2,revision:2,id:"optimism-4",courseId:"optimism",locale:"fr",title:"Pas de réponse ? Vérifie ce que tu sais",goal:"Distingue un fait connu d’une prédiction, puis vérifie un élément disponible sur ton revers.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Toujours pas de réponse, et tu imagines déjà le verdict ? Vérifie un fait avant d’organiser la suite.",reason:{id:"optimism-4-reason",label:"Quels éléments te feraient changer ton prochain geste ?",kind:"text",maxLength:160,optional:!0,suggestions:["Vérifier avant de supposer","Garder une inquiétude fondée visible","Demander le fait qui manque"]},why:{id:"optimism-4-direction",label:"Pourquoi ce geste compte-t-il dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Reprends ton revers. « Pas de réponse aujourd’hui » est connu. « On m’a encore rejeté » reste une prédiction sans éléments qui la confirment. Une réponse équilibrée garde les inquiétudes fondées et les informations manquantes. Elle peut rester incertaine ou désagréable.","Une fiche de pensées est un outil clinique documenté. Les résultats d’un traitement complet ne prouvent pas son efficacité seule. Limite la vérification : fait connu, sens supposé, éléments disponibles, prochain geste. Pose une question neutre ou corrige le problème confirmé. Arrête si l’analyse répétée augmente la détresse. L’inquiétude n’a pas à diminuer."],example:{title:"Camille vérifie l’absence de réponse",text:"Camille n’a pas de réponse à sa correction et sait son responsable en déplacement. Au point prévu, elle demande si l’explication du budget convient. Il répond : « Presque. Ajoute l’hypothèse. » Elle le fait. Elle craignait un refus plus large. Dans ses notes, elle garde le retour reçu, sans conclure que toutes ses inquiétudes étaient infondées."}},move:{invitation:"Vérifie un fait disponible sur le même revers. Agis selon ce qu’il indique.",instructions:["Sépare ce que tu sais de ce que tu supposes.","Pose une question neutre ou corrige le problème confirmé."],prompts:[],suggestions:{action:["Poser une question neutre sur l’avancement","Vérifier une fois l’exigence concernée","Corriger le problème confirmé"],minimum:["Envoyer une question pour vérifier les faits","Vérifier une exigence pertinente","Corriger une erreur confirmée"],cue:["Au point prévu, sans risque","Quand l’information est disponible","Avant d’agir sur ma prédiction"],place:["Par une messagerie sûre","Avec l’exigence réelle sous les yeux"],fallback:["Vérifier plus tard, au moment adapté","Demander plutôt une aide pratique","Arrêter l’analyse en boucle ; faire une pause"],observation:["Ce que je savais avant la vérification","Ce que la réponse a établi","Si les faits ont changé mon plan"],minutes:[2,1,5],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Poser une question neutre sur l’avancement",minimum:"Envoyer une question pour vérifier les faits",minutes:2,cueHint:"Au point prévu, sans risque",placeHint:"Par une messagerie sûre",obstacleHint:"J’analyse au lieu de chercher l’information.",fallbackHint:"Vérifier plus tard, au moment adapté",observationHint:"Ce que je savais avant la vérification"},stopRule:"N’utilise pas cet exercice en cas de danger, maltraitance, automutilation ou symptômes graves. Arrête l’analyse en boucle ; demande du soutien.",accessibleAlternative:"Utilise ton moyen de communication habituel, une aide pratique ou une limite qui te protège."},result:{question:"As-tu fait le minimum que tu avais choisi ?",observationPrompt:"Qu’as-tu fait, et que s’est-il passé ensuite ?"},judgment:{primary:{id:"optimism-4-deadline-check-decision",scenario:"Camille n’a pas de réponse à son projet. Son responsable, en déplacement, peut en parler au point d’aujourd’hui. Le dépôt ferme dans trente minutes. Une correction ou une proposition de secours prendrait vingt minutes.",question:"Quel premier geste utilise le mieux le temps restant ?",options:[{id:"optimism-4-submit-current",text:"Déposer la version actuelle, car le déplacement pourrait expliquer le silence et la date limite approche.",feedback:"Déposer maintenant protège le délai. Mais le déplacement ne prouve pas que le projet respecte les consignes. Un bref échange peut révéler une correction et laisser vingt minutes pour la faire."},{id:"optimism-4-check-uncertainty",text:"Garder la cause ouverte, poser la question au point prévu et corriger selon la réponse reçue.",feedback:"Cette option vérifie l’incertitude pertinente tant que le responsable est disponible et qu’il reste du temps. La réponse peut orienter vers une correction ou une solution de secours. L’inquiétude n’a pas à diminuer."},{id:"optimism-4-backup-and-timeline",text:"Commencer la proposition de secours et demander quand la décision arrivera, en gardant les deux possibilités ouvertes.",feedback:"Une solution de secours préserve les options quand aucun retour n’est disponible. Ici, le responsable est disponible et chaque option prend vingt minutes. Vérifie d’abord le projet pour consacrer le temps restant au besoin confirmé."}],bestOptionId:"optimism-4-check-uncertainty"}},carry:{takeaway:"Une réponse équilibrée garde l’inquiétude fondée, l’incertitude et un moyen utile de vérifier.",followUp:{questionId:"optimism-4-return",question:"Qu’as-tu appris en vérifiant ce fait ? As-tu adapté la suite à ces éléments ?",observationPrompt:"Qu’ont établi les faits, et qu’est-ce qui reste inconnu ?",adjustmentPrompt:"Quel prochain geste doit changer selon ces éléments ?"}},goDeeper:{sections:[{heading:"Les résultats concernent un traitement complet",paragraphs:["Hofmann et ses collègues ont recensé 269 méta-analyses de TCC et en ont examiné 106 représentatives [O06]. Ce sont des nombres de synthèses, pas 269 essais isolés de fiches de pensées. L’article résume des traitements composés de plusieurs éléments, appliqués à différents problèmes. Il ne donne ni effectif global unique ni effet universel pour cet exercice.","Un traitement complet combine plusieurs méthodes et du soutien. Ses résultats ne permettent pas d’isoler l’effet de cette brève vérification. Utilise-la pour éclaircir une incertitude pratique : quelle exigence compte, faut-il corriger, quand viendra la décision ? Sans nouvelle information disponible, garde l’incertitude visible. Refaire la même analyse ne fournit pas une réponse supplémentaire.","La fiche du Beck Institute décrit une méthode clinique [O13]. Elle n’établit pas à elle seule son efficacité isolée. Cette leçon en propose une adaptation raccourcie : rendre une prédiction vérifiable, puis relier cette vérification à l’action pratique sur laquelle tu travailles déjà."]},{heading:"Les évaluations décrivent, elles ne fixent pas un objectif",paragraphs:["La fiche de pensées documentée comprend des évaluations de pensées et d’émotions, des éléments pour les examiner, une réponse équilibrée et de nouvelles évaluations [O13]. Ces nombres peuvent décrire un changement. Exiger une baisse pousserait plutôt à noter la réponse souhaitée. La réponse équilibrée doit respecter les faits, même si l’inquiétude reste crédible.","ODA n’impose ni étiquette de piège de pensée ni score émotionnel particulier. « Ce que je sais » et « Ce que je suppose » peuvent suffire pour choisir une vérification. Une inquiétude fondée peut demander une correction, une limite ou de l’aide pratique. Une autre phrase rassurante n’est pas toujours le prochain geste utile.","Le NHS décrit les TCC comme un traitement professionnel structuré [O16]. Tu peux arrêter une analyse en autonomie qui augmente la détresse ou se répète sans information nouvelle. Cherche une aide adaptée si besoin. Garde la réponse et l’action réelles dans tes notes. Une inquiétude réduite ne prouve pas que la tâche a été faite."]}],sourceIds:["optimism-hofmann","optimism-beck-thought-record","optimism-nhs-cbt"]}},{schemaVersion:2,revision:2,id:"optimism-5",courseId:"optimism",locale:"fr",title:"Encore annulé ? Demande clairement ce qu’il te faut",goal:"Examine une supposition ordinaire sur le même revers, puis formule une demande ou limite sans risque.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Encore annulé ? Ne conclus pas trop vite. Garde la demande nécessaire.",reason:{id:"optimism-5-reason",label:"Quelle demande ou limite reste nécessaire après réflexion ?",kind:"text",maxLength:160,optional:!0,suggestions:["Demander directement au lieu de supposer","Garder une limite nécessaire","Rester ouvert sans tout me reprocher"]},why:{id:"optimism-5-direction",label:"Pourquoi ce geste compte-t-il dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Leurs intentions peuvent rester inconnues et ton besoin réel. Reprends ton revers. Après une relecture annulée sans risque, « Il s’en fiche » dépasse peut-être les faits. « Il me faut un créneau adapté » peut rester vrai.","Un programme long accompagné de questionnement a été testé dans un essai randomisé. Cela ne valide pas quatre questions en autonomie comme traitement. Utilise-les si elles aident, puis formule ta demande ou limite. Ni culpabilité ni exemples inventés ne sont exigés. N’utilise pas cet exercice face au danger ou à la maltraitance. La curiosité n’impose ni contact ni abandon de ta protection."],example:{title:"Camille demande une relecture claire",text:"Un collègue annule deux fois la relecture du rapport de Camille. À 8 h, elle interroge « Il s’en fiche », sans affirmer le contraire. Elle écrit : « Peux-tu relire avant jeudi ? Sinon, je demanderai à quelqu’un d’autre. » Il ne peut pas s’engager. Elle note sa demande et trouve une autre relecture sûre. La déception reste."}},move:{invitation:"Formule la demande ou limite nécessaire à cet essai sans risque.",instructions:["Garde tes besoins et limites.","Envoie la demande ; un accord n’est pas ton minimum."],prompts:[],suggestions:{action:["Demander un créneau de relecture adapté","Poser une limite pratique pour la relecture","Choisir une autre voie sûre pour un retour"],minimum:["Envoyer une demande de délai claire","Exprimer une limite avec respect","Demander une autre relecture"],cue:["Après l’annulation d’une relecture sans risque","Au prochain échange adapté","Quand la limite convenue est atteinte"],place:["Dans l’échange de relecture sûr","Par mon canal habituel"],fallback:["Choisir une autre personne sûre pour relire","Choisir plutôt une aide pratique","Suspendre le questionnement qui augmente la détresse"],observation:["La demande que j’ai faite","La réponse, même sans accord","Si la limite restait adaptée"],minutes:[2,1,5],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Demander un créneau de relecture adapté",minimum:"Envoyer une demande de délai claire",minutes:2,cueHint:"Après l’annulation d’une relecture sans risque",placeHint:"Dans l’échange de relecture sûr",obstacleHint:"La réflexion remplace une demande directe encore nécessaire.",fallbackHint:"Choisir une autre personne sûre pour relire",observationHint:"La demande que j’ai faite"},stopRule:"N’utilise pas cet exercice en cas de danger, maltraitance, automutilation ou symptômes graves. Tu n’as pas à te blâmer ; suspends le questionnement éprouvant.",accessibleAlternative:"Utilise ton moyen de communication habituel, une aide pratique ou une limite qui te protège."},result:{question:"As-tu fait le minimum que tu avais choisi ?",observationPrompt:"Qu’as-tu fait, et que s’est-il passé ensuite ?"},judgment:{primary:{id:"optimism-5-decision",scenario:"Un collègue avec qui Camille peut échanger sans risque a annulé sa relecture deux fois. Ses raisons sont floues. Elle a besoin d’un retour cette semaine.",question:"Quelle réponse garde la curiosité et une limite utile ?",options:[{id:"optimism-5-finish-alone",text:"Finir seule pour limiter la tension, puis envisager de solliciter ce collègue sur un prochain projet.",feedback:"Travailler seule peut convenir si la relecture est facultative ou si Camille sait la faire. Ici, un retour reste nécessaire cette semaine. Demande un créneau adapté ou une autre personne sûre."},{id:"optimism-5-flexible-slot",text:"Proposer un autre créneau souple, sans fixer de limite, pour laisser le collègue choisir selon ses disponibilités.",feedback:"La souplesse peut préserver la coopération. Mais deux annulations et le délai de cette semaine rendent cet arrangement risqué. Associe un créneau adapté à une autre option pour couvrir le vrai besoin."},{id:"optimism-5-request-with-limit",text:"Ne pas conclure sur ses intentions, demander un créneau adapté et prévoir quelqu’un d’autre s’il est indisponible.",feedback:"Cette option associe l’incertitude à un besoin concret. Le collègue peut refuser ; Camille utilise alors l’alternative. Envoyer la demande est son action. La coopération reste un résultat qu’elle ne contrôle pas."}],bestOptionId:"optimism-5-request-with-limit"}},carry:{takeaway:"Examine l’histoire incertaine sans renoncer à ta vraie demande ni à ta limite.",followUp:{questionId:"optimism-5-return",question:"Qu’a changé ta demande ou ta limite ? Cette limite sert-elle encore ce qui compte pour toi ?",observationPrompt:"Qu’a changé ta demande ou ta limite, même sans réponse ?",adjustmentPrompt:"La limite convient-elle encore, ou faut-il l’ajuster ?"}},goDeeper:{sections:[{heading:"L’essai randomisé était intensif et accompagné",paragraphs:["Landau et ses collègues ont testé la réduction du stress par le questionnement dans un essai randomisé enregistré, auprès de 100 femmes porteuses de variants BRCA [O11]. Le programme durait douze semaines : groupes de trois heures chaque semaine et une heure de pratique accompagnée, comparés aux soins habituels. Certains résultats de bien-être s’amélioraient. Le groupe témoin ne recevait pas une attention équivalente.","Ces résultats ne montrent pas que quatre brèves questions en autonomie constituent un traitement, que la méthode équivaut aux TCC ou qu’elle convient à la maltraitance et au traumatisme. Le public, la durée et l’accompagnement diffèrent beaucoup de cette situation ordinaire de relecture. Une demande a besoin d’une raison pratique, pas d’une promesse d’amélioration clinique.","L’exercice de demande proposé par ODA est une adaptation éducative. Si la réflexion t’aide, relie-la à la relecture dont tu as besoin. Demande un moment adapté et garde une autre possibilité. Ta demande peut être faite alors que son effet reste inconnu. La coopération d’autrui ne mesure pas ton optimisme."]},{heading:"Un questionnement facultatif, sans retournement imposé",paragraphs:["Les instructions de Byron Katie proposent quatre questions : la pensée est-elle vraie ? Peux-tu en être certain ? Comment influence-t-elle ta réponse ? Que change le fait de la tenir moins fermement ? [O15] Elles décrivent ensuite des retournements avec des exemples réels. C’est une source de méthode, pas la preuve d’une efficacité thérapeutique propre aux questions seules.","Tout retournement reste facultatif. Aucun nombre fixe d’exemples n’est nécessaire ; n’en invente pas. Tu n’as pas à découvrir que le tort subi serait ta responsabilité. Une demande claire ou une limite peut rester nécessaire après réflexion, même si les intentions de l’autre demeurent inconnues.","Réserve ce questionnement aux frustrations ordinaires et sans risque. Le NHS indique des voies d’accès au traitement professionnel [O16] ; ODA ne le remplace pas. Danger, maltraitance, risque d’automutilation et symptômes graves demandent protection et soutien adapté. Tu peux arrêter cet exercice et choisir une réponse pratique."]}],sourceIds:["optimism-landau-inquiry","optimism-katie-instructions","optimism-nhs-cbt"]}},{schemaVersion:2,revision:2,id:"optimism-6",courseId:"optimism",locale:"fr",title:"Semaine dure ? Garde le geste qui aide",goal:"Consolide le même essai avec tes actions réelles, les conditions utiles et une prochaine occasion faisable.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Semaine difficile. Quel geste utile ou soutien mérite d’être repris ?",reason:{id:"optimism-6-reason",label:"Qu’est-ce qui t’a aidé à avancer ? Quel problème demande encore une action ?",kind:"text",maxLength:160,optional:!0,suggestions:["Reprendre une condition utile","Garder le problème non résolu visible","Choisir un prochain essai faisable"]},why:{id:"optimism-6-direction",label:"Pourquoi ce geste compte-t-il dans ta semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Revois le même revers et ton action. Qu’as-tu fait ? Qu’est-ce qui a aidé ? Que reste-t-il à résoudre ? Une semaine dure peut contenir du soutien utile. Choisis la suite selon ces faits, sans exiger de te sentir bien.","L’étude originale des « trois bonnes choses » demandait trois événements et leurs causes, chaque soir pendant une semaine. Une réplication trouvait aussi des gains de bonheur avec un placebo positif, affaiblissant l’idée d’un effet propre à l’exercice. Relève un événement réellement utile, ou aucun. Garde le même essai sans ajouter de rituel chaque soir."],example:{title:"Camille reprend ce qui a aidé",text:"Vendredi, le rapport de Camille attend encore une validation. Ses notes montrent qu’une autre relecture a indiqué une correction précise. À son bureau, elle la fait et prévoit le prochain échange. Elle reconnaît l’aide sans déclarer la semaine réussie. Son essai garde ce rapport, une tâche réduite et une date réaliste pour revenir dessus."}},move:{invitation:"Revois le même essai. Reprends une condition utile et un geste faisable.",instructions:["Garde les problèmes non résolus et l’aide reçue visibles.","Choisis un prochain essai, une demande de soutien ou une pause."],prompts:[],suggestions:{action:["Appliquer la correction indiquée","Refaire le geste qui a aidé","Redemander le soutien utile"],minimum:["Corriger un élément confirmé du projet","Terminer une petite étape utile","Envoyer une demande de soutien précise"],cue:["À ma prochaine séance sur le texte","Quand un retour utile est disponible","Au moment choisi pour le soutien"],place:["Dans mon texte actuel","Par un canal de soutien sûr"],fallback:["Réduire le geste utile pour avancer","Faire une pause et choisir quand revenir","Utiliser une autre voie de soutien faisable"],observation:["Ce qui a aidé l’action réelle","Le problème resté sans solution","Si le prochain geste convenait à ma semaine"],minutes:[2,1,5],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}]},suggested:{action:"Appliquer la correction indiquée",minimum:"Corriger un élément confirmé du projet",minutes:2,cueHint:"À ma prochaine séance sur le texte",placeHint:"Dans mon texte actuel",obstacleHint:"J’ajoute des rituels au lieu d’améliorer l’action utile.",fallbackHint:"Réduire le geste utile pour avancer",observationHint:"Ce qui a aidé l’action réelle"},stopRule:"N’utilise pas cet exercice en cas de danger, maltraitance, automutilation ou symptômes graves. Arrête l’analyse en boucle ; demande du soutien.",accessibleAlternative:"Utilise ton moyen de communication habituel, une aide pratique ou une limite qui te protège."},result:{question:"As-tu fait le minimum que tu avais choisi ?",observationPrompt:"Qu’as-tu fait, et que s’est-il passé ensuite ?"},judgment:{primary:{id:"optimism-6-correction-scope-decision",scenario:"On a signalé à Camille une seule hypothèse manquante et confirmé que le reste du rapport respecte les consignes. Il reste vingt minutes avant le dépôt. La correction prend cinq minutes ; l’approbation reste incertaine.",question:"Quel geste utilise le mieux ce retour utile ?",options:[{id:"optimism-6-repeat-helpful-cause",text:"Faire la correction confirmée, déposer dans le délai et noter le résultat sans prédire l’approbation.",feedback:"Cette option utilise le retour précis en gardant l’approbation incertaine. La correction tient dans le temps restant et sert le même rapport. Note ce qui a changé et toute réponse, même absente."},{id:"optimism-6-check-scope",text:"Demander une nouvelle vérification de l’ensemble avant de corriger, pour éviter de manquer un problème plus large.",feedback:"Une nouvelle vérification aide quand l’étendue du problème est floue. Ici, elle est déjà confirmée. Attendre peut épuiser le temps restant sans éclaircir de nouvelle incertitude. Fais d’abord la correction précise."},{id:"optimism-6-request-extension",text:"Demander un bref délai supplémentaire pour relire tout le rapport avant d’appliquer la correction.",feedback:"Un délai supplémentaire peut protéger le travail si le temps ou les capacités manquent. Ici, la correction tient dans le créneau. Cette demande ajoute une coordination sans traiter un obstacle identifié. La relecture générale peut attendre."}],bestOptionId:"optimism-6-repeat-helpful-cause"}},carry:{takeaway:"Reprends ce qui a aidé et un geste faisable, sans nier la difficulté de la semaine.",followUp:{questionId:"optimism-6-return",question:"La condition reprise a-t-elle aidé ton action ? Que faut-il encore corriger, soutenir ou arrêter ?",observationPrompt:"Quelle condition a aidé, et que reste-t-il à résoudre ?",adjustmentPrompt:"Reprendre cette condition, changer le geste, demander du soutien ou arrêter ?"}},goDeeper:{sections:[{heading:"La méthode étudiée : trois événements et leurs causes",paragraphs:["Dans l’essai en ligne original de Seligman et ses collègues, les participants notaient trois choses bien passées et leurs causes, chaque soir pendant une semaine [O07]. Il comptait 577 répondants au départ ; l’analyse portait sur 411 personnes ayant terminé le suivi, surtout des volontaires blancs et diplômés. Les exercices et la comparaison fondée sur un souvenir ancien étaient attribués au hasard. La poursuite de la pratique ne l’était pas.","L’essai original signalait des changements aux questionnaires de bonheur et de dépression. Il ne montre pas que poursuivre la pratique causait le maintien ultérieur des effets, que dix minutes sont nécessaires ou que la gratitude traite la dépression. Une réplication a aussi trouvé des améliorations du bonheur avec un placebo positif, sans démontrer un bénéfice propre sur la dépression [O08].","Tu peux choisir séparément l’exercice original d’une semaine s’il te convient. Relever un événement bon ou neutre, ou faire une pause lors d’une soirée difficile, est une adaptation respectueuse. Ce n’est pas la méthode testée. La fin de ce parcours consolide plutôt l’action que tu essaies déjà pour avancer."]},{heading:"La semaine suivante peut rester incertaine",paragraphs:["La description du programme de formation à la résilience propose d’envisager le pire, le meilleur et le plus probable avant de faire un plan [O14]. Elle n’établit pas l’efficacité propre à ce bref exercice. Utilise-le seulement pour prévoir une incertitude précise dans ton essai actuel, sans ajouter un rituel obligatoire.","Une attention réaliste garde la condition utile et le problème restant. L’aide d’une personne peut compter alors que le rapport reste non validé. Ce qui a aidé peut être une question précise, du temps dégagé ou du soutien. Reprends cet élément seulement s’il convient à la prochaine occasion. La gratitude n’est pas exigée.","Revois les mêmes faits avant la semaine suivante. Garde un minimum utile, un repère reconnaissable pour commencer et une solution de repli faisable. Choisis soutien, repos, limite ou arrêt si nécessaire. Les plans futurs, la réflexion et les réponses au quiz restent distincts des essais réels. Reviens sur ce qui s’est passé, même incertain ou sans réponse."]}],sourceIds:["optimism-three-good-things","optimism-mongrain","optimism-reivich-mrt"]}}],l=[{id:"optimism-1",practice:["Choisis un revers ordinaire. Essaie une possibilité encore ouverte, puis note ce qui s’est passé.","Essaie le minimum enregistré au repère choisi, ou note une pause.","Note ici le résultat réel ; reviens à la date prévue pour choisir le prochain essai."],correct:1,photo:{id:"1527580094867-0e719f119120",alt:"Une personne traverse des rochers gris à l’aube, en attendant le lever du soleil"}},{id:"optimism-2",practice:["Reprends le même revers. Nomme une cause exacte, puis fais la correction qu’elle indique.","Essaie le minimum enregistré au repère choisi, ou note une pause.","Note ici le résultat réel ; reviens à la date prévue pour choisir le prochain essai."],correct:2,photo:{id:"1509029032154-54ba8b3216d4",alt:"Un homme à lunettes regarde pensivement par une fenêtre"}},{id:"optimism-3",practice:["Reprends le même revers. Examine brièvement la croyance, puis fais une réponse juste.","Essaie le minimum enregistré au repère choisi, ou note une pause.","Note ici le résultat réel ; reviens à la date prévue pour choisir le prochain essai."],correct:0,photo:{id:"1643148636630-0b0fb138fc74",alt:"Une personne écrit au stylo dans un carnet"}},{id:"optimism-4",practice:["Vérifie un fait disponible sur le même revers. Agis selon ce qu’il indique.","Essaie le minimum enregistré au repère choisi, ou note une pause.","Note ici le résultat réel ; reviens à la date prévue pour choisir le prochain essai."],correct:1,photo:{id:"1681396059172-7532b1ef8b47",alt:"Un carnet ouvert sur une table dans la douce lumière du matin"}},{id:"optimism-5",practice:["Face à cette incertitude sans risque, formule la demande ou la limite nécessaire à ton essai.","Essaie le minimum enregistré au repère choisi, ou note une pause.","Note ici le résultat réel ; reviens à la date prévue pour choisir le prochain essai."],correct:2,photo:{id:"1503541517233-120571491cf3",alt:"Un homme assis sur un banc, les yeux fermés, entouré d’arbres"}},{id:"optimism-6",practice:["Revois le même essai. Reprends une condition utile et choisis la prochaine action faisable pour avancer.","Essaie le minimum enregistré au repère choisi, ou note une pause.","Note ici le résultat réel ; reviens à la date prévue pour choisir le prochain essai."],correct:0,photo:{id:"1750885847789-f5748b585e3a",alt:"Une femme sur un balcon regarde la ville"}}],c={id:"optimism",title:"Un revers t’envahit ? Trouve ton prochain geste",subtitle:"Six leçons pour examiner un revers, agir à ta mesure et apprendre du résultat réel.",description:"Redonne sa juste place à un revers ordinaire. Garde les faits douloureux, vérifie les interprétations incertaines et choisis une réponse concrète pour la vie que tu veux.",outcome:"Un revers examiné avec justesse, une action pour avancer et un plan pour revenir sur les faits.",scope:"Pour les adultes qui ont tendance à abandonner, se blâmer ou prévoir le pire après un revers. Ce parcours s’inspire de l’optimisme appris de Martin Seligman, des thérapies comportementales et cognitives (TCC) et de The Work de Byron Katie. C’est une démarche personnelle, pas un traitement de la dépression, de l’anxiété ou d’un autre trouble. Elle ne remplace ni thérapie ni médicaments. Si le désespoir persiste ou que le quotidien devient difficile, parle à un médecin ou à un professionnel de santé mentale. Tu peux demander de l’aide plus tôt. Pour des pensées suicidaires ou une crise émotionnelle, contacte l’aide de crise locale. Aux États-Unis, appelle le 988 ou envoie un SMS au 988. En cas de danger immédiat, contacte les services d’urgence locaux.",photo:{id:"1465188162913-8fb5709d6d57",alt:"Une femme marche sur une crête dans la lumière dorée du soir"},lang:"fr",lessons:r.map((e,o)=>{const n=l[o],i=e.judgment.primary,s=i.options.find(t=>t.id===i.bestOptionId),a=i.options.filter(t=>t.id!==i.bestOptionId).map(t=>t.text);return a.splice(n.correct,0,s.text),{...n,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,reflection:e.direction.reason.label,question:`${i.scenario} ${i.question}`,options:a,feedback:s.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds}})},p=Object.freeze(Object.defineProperty({__proto__:null,COURSE:c,LESSONS_V2:r,SOURCES:u},Symbol.toStringTag,{value:"Module"}));export{p as o};
